begin;
do $publish$ declare bid uuid; applied jsonb; begin
if exists(select 1 from businesses where name ilike '%Silva%Pet%' or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%2096094665' or website ilike '%nextdoor.com/pages/1957-tracy-ca%') then raise exception 'Duplicate needs individual review'; end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Silva Pet Care Services','Pet Services','Service area only',null,'(209) 609-4665','https://nextdoor.com/pages/1957-tracy-ca/','Public business page advertises in-home pet sitting and dog walking for Tracy residents only. It says overnight service in clients’ homes is not offered. Call or text to confirm your address, pet needs, visit schedule, full quote and available dates. No public visitor office or holiday availability established.','approved',true,false,null,0,'editorial_first_party','https://nextdoor.com/pages/1957-tracy-ca/','operator_published_business_page_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://nextdoor.com/pages/1957-tracy-ca/',array['business identity','public phone','advertised services','explicit service city','overnight service limit'],array['Tracy'],array['pet sitting','dog walking'],'Fresh normal-browser reading November16,2026 of operator-published Nextdoor business page. Our story explicitly says Tracy residents only, client-home pet sitting, dog walking and no overnight service in clients homes; public2096094665 call/text route shown. Operator activity dated September20,2024 corroborates advertised scope but is NOT current availability. This desk check is of published business information, not authenticated MoHoLocal ownership, credentials, experience, quality, safety, insurance, reviews or Thanksgiving availability. No MH/Lathrop/Manteca coverage inferred. No visitor address established, images/testimonials/awards copied, form or message sent.');
select to_jsonb(b) into applied from businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}',applied||jsonb_build_object('service_areas',array['Tracy'],'service_tags',array['pet sitting','dog walking']),'Individually checked public operator business page; explicit city/service limits, no seed publication','https://nextdoor.com/pages/1957-tracy-ca/');
end $publish$;
commit;
select id,name from businesses where name='Silva Pet Care Services';
